//! SYSVOL and NETLOGON data from the built-in collector, against
//! `testdata/sysvol` (generated by `scripts/gen_sysvol_fixture.py`, which
//! lists what is planted).

use std::path::PathBuf;

use pathwarden_core::findings::{self, Category, Context, Finding, RuleSettings, Severity};
use pathwarden_core::model::EdgeKind;
use pathwarden_core::opengraph::coverage::RunSources;
use pathwarden_core::retest;
use pathwarden_core::state::{self, ResolveScope};
use pathwarden_core::{load, remediation, report, AdGraph, IngestStats, LoadOptions};

const NOW: i64 = 1_791_417_600;
const SIDECAR: &str = "20261001020000_pathwarden-sysvol.json";

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/sysvol")
}

fn load_from(paths: &[PathBuf]) -> (AdGraph, IngestStats) {
    load(paths, &LoadOptions::default()).expect("fixture loads")
}

fn run(g: &AdGraph, stats: &IngestStats) -> Vec<Finding> {
    let settings = RuleSettings {
        now: NOW,
        ..RuleSettings::default()
    };
    findings::evaluate(&Context::new(g, &stats.trusts, &settings), &[])
}

fn titles(all: &[Finding], rule: &str) -> Vec<String> {
    let mut t: Vec<String> = all
        .iter()
        .filter(|f| f.rule == rule)
        .map(|f| f.title.clone())
        .collect();
    t.sort();
    t
}

/// The fixture's AD files plus a sidecar edited by `f`, in a temp folder.
fn with_sidecar(name: &str, f: impl FnOnce(&mut serde_json::Value)) -> PathBuf {
    with_files(name, f, false)
}

/// As [`with_sidecar`]; with `carol_ace`, CAROL also has GenericAll on
/// ALICE (a Domain Admin) in AD: a PW-003 read over LDAP that has nothing to
/// do with SYSVOL.
fn with_files(name: &str, f: impl FnOnce(&mut serde_json::Value), carol_ace: bool) -> PathBuf {
    let mut f = Some(f);
    let out = std::env::temp_dir().join(format!("pw-sysvol-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&out);
    std::fs::create_dir_all(&out).unwrap();
    for e in std::fs::read_dir(dir()).unwrap() {
        let p = e.unwrap().path();
        let file = p.file_name().unwrap().to_string_lossy().to_string();
        if file == SIDECAR {
            let mut v: serde_json::Value =
                serde_json::from_slice(&std::fs::read(&p).unwrap()).unwrap();
            (f.take().unwrap())(&mut v);
            std::fs::write(out.join(&file), serde_json::to_vec(&v).unwrap()).unwrap();
        } else if carol_ace && file.ends_with("_users.json") {
            let mut v: serde_json::Value =
                serde_json::from_slice(&std::fs::read(&p).unwrap()).unwrap();
            let alice = v["data"]
                .as_array_mut()
                .unwrap()
                .iter_mut()
                .find(|u| u["Properties"]["name"] == "ALICE@SYS.LOCAL")
                .unwrap();
            alice["Aces"] = serde_json::json!([{
                "PrincipalSID": "S-1-5-21-7000-7000-7000-1103",
                "PrincipalType": "User",
                "RightName": "GenericAll",
                "IsInherited": false
            }]);
            std::fs::write(out.join(&file), serde_json::to_vec(&v).unwrap()).unwrap();
        } else {
            std::fs::copy(&p, out.join(&file)).unwrap();
        }
    }
    out
}

/// A sidecar as a password collection writes it: the folder and logon
/// script permissions can't be read (no QUERY_INFO in the SMB client), GPP
/// passwords are read.
fn password_mode(v: &mut serde_json::Value) {
    for part in ["gpo_acl", "logon_script_acl"] {
        v["checks"][part] = serde_json::json!({
            "status": "not_collected",
            "reason": "the SMB client can't read security descriptors"
        });
    }
    v["gpos"] = serde_json::json!([]);
    v["logon_scripts"] = serde_json::json!([]);
}

/// The PW-003 for CAROL's GenericAll on ALICE.
fn carol_finding(all: &[Finding]) -> &Finding {
    all.iter()
        .find(|f| {
            f.rule == "PW-003"
                && f.sources.is_empty()
                && f.affected.iter().any(|a| a.name == "CAROL@SYS.LOCAL")
        })
        .unwrap_or_else(|| panic!("no PW-003 for CAROL: {:#?}", titles(all, "PW-003")))
}

/// The SYSVOL part keys a run recorded before `LastRun::sources_exact`:
/// every part of the sidecar's domain, read or not.
fn legacy_keys() -> Vec<String> {
    pathwarden_core::sysvol::Part::ALL
        .iter()
        .map(|p| pathwarden_core::opengraph::source_key(&p.source("SYS.LOCAL")))
        .collect()
}

fn has_edge(g: &AdGraph, from: &str, to: &str, kind: EdgeKind) -> bool {
    let (a, b) = (g.find(from)[0], g.find(to)[0]);
    g.inner()
        .edges_connecting(a, b)
        .any(|e| *e.weight() == kind)
}

#[test]
fn edges_follow_the_file_permissions_and_the_whitelist() {
    let (g, stats) = load_from(&[dir()]);
    assert_eq!(stats.sysvol.len(), 1, "{:?}", stats.skipped_files);
    let s = &stats.sysvol[0];
    assert_eq!(
        (s.gpo_edges, s.script_edges, s.gpp_files),
        (2, 1, 1),
        "{s:?}"
    );
    assert_eq!(s.unresolved, 0, "{s:?}");
    let ddp = "DEFAULT DOMAIN POLICY@SYS.LOCAL";
    assert!(has_edge(&g, "BOB@SYS.LOCAL", ddp, EdgeKind::WriteGpoFiles));
    assert!(has_edge(
        &g,
        "EVE@SYS.LOCAL",
        "WALLPAPER@SYS.LOCAL",
        EdgeKind::WriteGpoFiles
    ));
    assert!(has_edge(
        &g,
        "DAVE@SYS.LOCAL",
        "ALICE@SYS.LOCAL",
        EdgeKind::WriteLogonScript
    ));
    // Allowed to edit the GPO in AD: its folder write is consistent.
    assert!(!has_edge(
        &g,
        "WALLADMIN@SYS.LOCAL",
        "WALLPAPER@SYS.LOCAL",
        EdgeKind::WriteGpoFiles
    ));
    // Default writers never get an edge, and read access is not write.
    for (_, n) in g.nodes() {
        let ix = g.lookup(&n.id).unwrap();
        for e in g.inner().edges_directed(ix, petgraph::Direction::Outgoing) {
            if matches!(
                e.weight(),
                EdgeKind::WriteGpoFiles | EdgeKind::WriteLogonScript
            ) {
                assert!(
                    ["BOB@SYS.LOCAL", "EVE@SYS.LOCAL", "DAVE@SYS.LOCAL"].contains(&n.name.as_str()),
                    "unexpected writer {}",
                    n.name
                );
            }
        }
    }
    // Both edges are traversable control.
    assert!(EdgeKind::WriteGpoFiles.is_traversable());
    assert!(EdgeKind::WriteLogonScript.is_traversable());
    assert_eq!(
        EdgeKind::from_name("writegpofiles"),
        Some(EdgeKind::WriteGpoFiles)
    );
    // The logon script property is kept.
    let alice = g.node(g.find("ALICE@SYS.LOCAL")[0]);
    assert_eq!(alice.props.logonscript.as_deref(), Some("admin.bat"));
}

#[test]
fn rules_report_paths_drift_and_gpp_passwords() {
    let (g, stats) = load_from(&[dir()]);
    let all = run(&g, &stats);
    assert_eq!(
        titles(&all, "PW-003"),
        [
            "BOB@SYS.LOCAL has WriteGPOFiles on DEFAULT DOMAIN POLICY@SYS.LOCAL",
            "DAVE@SYS.LOCAL has WriteLogonScript on ALICE@SYS.LOCAL",
        ]
    );
    let bob = all
        .iter()
        .find(|f| f.rule == "PW-003" && f.title.starts_with("BOB"))
        .unwrap();
    // The fix names the folder and the ACE, with the command.
    assert!(
        bob.remediation.contains(
            r#"icacls "\\sys.local\SYSVOL\sys.local\Policies\{31B2F340-016D-11D2-945F-00C04FB984F9}" /remove:g *S-1-5-21-7000-7000-7000-1102"#
        ),
        "{}",
        bob.remediation
    );
    assert!(
        bob.remediation.contains(r"\Machine is inherited"),
        "{}",
        bob.remediation
    );
    assert_eq!(bob.sources, ["SYSVOL GPO permissions (SYS.LOCAL)"]);
    let dave = all
        .iter()
        .find(|f| f.rule == "PW-003" && f.title.starts_with("DAVE"))
        .unwrap();
    assert!(
        dave.remediation.contains(r"\\sys.local\NETLOGON\admin.bat"),
        "{}",
        dave.remediation
    );
    assert!(
        dave.remediation.contains("write and append"),
        "{}",
        dave.remediation
    );

    let drift: Vec<&Finding> = all.iter().filter(|f| f.rule == "PW-027").collect();
    assert_eq!(drift.len(), 2);
    let ddp = drift
        .iter()
        .find(|f| f.title.contains("DEFAULT DOMAIN"))
        .unwrap();
    let wall = drift
        .iter()
        .find(|f| f.title.contains("WALLPAPER"))
        .unwrap();
    assert_eq!(ddp.severity, Severity::High);
    assert_eq!(wall.severity, Severity::Medium);
    assert_eq!(wall.category, Category::Hygiene);
    assert!(
        wall.summary.contains("EVE@SYS.LOCAL (owner on"),
        "{}",
        wall.summary
    );
    assert!(
        wall.remediation.contains("/setowner *S-1-5-32-544"),
        "{}",
        wall.remediation
    );
    assert_eq!(wall.sources, ["SYSVOL GPO permissions (SYS.LOCAL)"]);

    let gpp: Vec<&Finding> = all.iter().filter(|f| f.rule == "PW-026").collect();
    assert_eq!(gpp.len(), 1);
    let gpp = gpp[0];
    assert_eq!(gpp.severity, Severity::Critical);
    assert_eq!(
        gpp.title,
        "Group Policy Preferences password in WALLPAPER@SYS.LOCAL (Groups.xml)"
    );
    assert!(gpp.summary.contains(r"SYS\svc_backup"), "{}", gpp.summary);
    assert!(gpp
        .affected
        .iter()
        .any(|a| a.name == "SVC_BACKUP@SYS.LOCAL"));
    assert_eq!(gpp.sources, ["SYSVOL GPP passwords (SYS.LOCAL)"]);
    // Nothing for the read-only logon script or the consistent editor.
    assert!(!all
        .iter()
        .any(|f| f.title.contains("CAROL") || f.title.contains("WALLADMIN")));
}

#[test]
fn plan_steps_say_what_to_change() {
    let (g, _) = load_from(&[dir()]);
    let plan = remediation::plan(&g, &pathwarden_core::analysis::Relevance::new(&g, NOW, 90));
    let step = plan
        .fixes
        .iter()
        .find(|f| f.edges.contains(&EdgeKind::WriteGpoFiles))
        .expect("a plan step for the SYSVOL folder");
    assert_eq!(
        report::step_headline(step),
        r#"Take away the write access of <b title="BOB@SYS.LOCAL">BOB</b> to the SYSVOL folder of the GPO <b title="DEFAULT DOMAIN POLICY@SYS.LOCAL">DEFAULT DOMAIN POLICY</b>"#
    );
    assert!(step.action.contains("/remove:g"), "{}", step.action);
    let script = plan
        .fixes
        .iter()
        .find(|f| f.edges.contains(&EdgeKind::WriteLogonScript))
        .expect("a plan step for the logon script");
    assert!(report::step_headline(script).contains("to the logon script of"));
}

#[test]
fn parts_not_read_are_held_not_fixed() {
    let (g, stats) = load_from(&[dir()]);
    let first = run(&g, &stats);
    let prev = state::reconcile(&state::FindingsState::default(), &first, 1, false).state;
    // The parts with edges (folder and logon script permissions); GPP
    // passwords add none.
    let keys = RunSources::from_analysis(&g, &stats).keys();
    assert_eq!(keys.len(), 2);

    // Next run: the folder permissions were not read (password collection)
    // and the GPP scan was partial.
    let partial = with_sidecar("partial", |v| {
        v["checks"]["gpo_acl"] =
            serde_json::json!({"status": "not_collected", "reason": "no Windows"});
        v["checks"]["gpp"]["status"] = "partial".into();
        v["gpos"] = serde_json::json!([]);
        v["gpp_passwords"] = serde_json::json!([]);
    });
    let (g2, stats2) = load_from(std::slice::from_ref(&partial));
    let second = run(&g2, &stats2);
    assert!(second
        .iter()
        .all(|f| f.rule != "PW-026" && f.rule != "PW-027"));
    let sources = RunSources::from_analysis(&g2, &stats2);
    let scope = ResolveScope::everything().with_sources(sources, &keys);
    let r = state::reconcile_scoped(&prev, &second, 2, false, &scope);
    // BOB's PW-003, both PW-027 and the PW-026 are held; DAVE's PW-003 is
    // still open (logon scripts were read).
    assert_eq!(r.counts.resolved, 0, "{:?}", r.resolved);
    assert_eq!(r.counts.held, 4);

    // A run that read everything and found them gone resolves them.
    let clean = with_sidecar("clean", |v| {
        v["gpos"] = serde_json::json!([]);
        v["gpp_passwords"] = serde_json::json!([]);
    });
    let (g3, stats3) = load_from(std::slice::from_ref(&clean));
    let third = run(&g3, &stats3);
    let scope =
        ResolveScope::everything().with_sources(RunSources::from_analysis(&g3, &stats3), &keys);
    let r = state::reconcile_scoped(&prev, &third, 3, false, &scope);
    assert_eq!((r.counts.resolved, r.counts.held), (4, 0));

    // No SYSVOL data at all (a SharpHound collection): held as well.
    let none = with_sidecar("none", |_| {});
    std::fs::remove_file(none.join(SIDECAR)).unwrap();
    let (g4, stats4) = load_from(std::slice::from_ref(&none));
    let fourth = run(&g4, &stats4);
    let scope =
        ResolveScope::everything().with_sources(RunSources::from_analysis(&g4, &stats4), &keys);
    let r = state::reconcile_scoped(&prev, &fourth, 4, false, &scope);
    assert_eq!(r.counts.resolved, 0);
    for d in [partial, clean, none] {
        let _ = std::fs::remove_dir_all(d);
    }
}

/// Compares `before` (recorded as `run` would, with `recorded` as its
/// `LastRun::sources` and `exact` as its `sources_exact`) with `after`, as
/// `run` and `retest` do: what `run` resolves and holds, and `retest`'s
/// verdict for `fp` with its details.
fn compare(
    before: &(AdGraph, IngestStats),
    recorded: Option<Vec<String>>,
    after: &(AdGraph, IngestStats),
    fp: &str,
) -> (state::Reconciled, retest::Verdict, Vec<String>) {
    let first = run(&before.0, &before.1);
    let prev = state::reconcile(&state::FindingsState::default(), &first, 1, false).state;
    let exact = recorded.is_none();
    let recorded =
        recorded.unwrap_or_else(|| RunSources::from_analysis(&before.0, &before.1).keys());
    let last = state::LastRun {
        version: state::STATE_VERSION,
        run_id: "1".into(),
        started_at: 1,
        finished_at: 1,
        collected_at: None,
        pathwarden: String::new(),
        collector_files: 0,
        domains: vec!["SYS.LOCAL".into()],
        trusted_domains: Some(Vec::new()),
        objects: 0,
        changes: state::ChangeCounts::default(),
        sources: recorded,
        sources_exact: exact,
        settings_files: Vec::new(),
        hosts: None,
    };
    let second = run(&after.0, &after.1);
    let sources = RunSources::from_analysis(&after.0, &after.1);
    let had = last.baseline_sources(&sources, &prev);
    // `run`
    let scope =
        ResolveScope::domains(&["SYS.LOCAL".to_string()], true).with_sources(sources.clone(), &had);
    let r = state::reconcile_scoped(&prev, &second, 2, false, &scope);
    // `retest --finding`
    let coverage = retest::Coverage {
        domains: vec!["SYS.LOCAL".into()],
        complete: true,
        missing_sources: scope.missing_sources.clone(),
        sources,
        ..Default::default()
    };
    let current: Vec<retest::FindingView> = second.iter().map(retest::FindingView::from).collect();
    let report = retest::compare(
        &retest::Baseline::from_state(&prev, "state"),
        &current,
        &coverage,
        &retest::Selection {
            fingerprints: vec![fp.to_string()],
            rules: Vec::new(),
        },
    )
    .unwrap();
    let x = &report.results[0];
    (r, x.verdict, x.details.clone())
}

/// The GOAD case: two password collections (SYSVOL permissions not
/// collected either time), and an AD ACE removed in between. The finding
/// rests on LDAP data only, so it is fixed: parts never collected can't
/// have carried its path.
#[test]
fn password_collections_resolve_a_removed_ace() {
    let before = with_files("pw-before", password_mode, true);
    let after = with_files("pw-after", password_mode, false);
    let (b, a) = (
        load_from(std::slice::from_ref(&before)),
        load_from(std::slice::from_ref(&after)),
    );
    let fp = carol_finding(&run(&b.0, &b.1)).fingerprint.clone();
    // Nothing of SYSVOL is recorded: no part added an edge.
    assert!(RunSources::from_analysis(&b.0, &b.1).keys().is_empty());

    for recorded in [None, Some(legacy_keys())] {
        let legacy = recorded.is_some();
        let (r, verdict, details) = compare(&b, recorded, &a, &fp);
        assert!(
            r.resolved.iter().any(|x| x.fingerprint == fp),
            "legacy {legacy}: {:?}, held {}",
            r.resolved,
            r.counts.held
        );
        assert_eq!(r.counts.held, 0, "legacy {legacy}");
        assert_eq!(
            verdict,
            retest::Verdict::Fixed,
            "legacy {legacy}: {details:?}"
        );
    }
    for d in [before, after] {
        let _ = std::fs::remove_dir_all(d);
    }
}

/// A finding whose path runs through `WriteGPOFiles` is held when the folder
/// permissions were not collected this run, and the message names the part.
#[test]
fn write_gpo_files_finding_held_when_the_part_is_not_collected() {
    let after = with_sidecar("gpo-after", password_mode);
    let (b, a) = (load_from(&[dir()]), load_from(std::slice::from_ref(&after)));
    let first = run(&b.0, &b.1);
    let bob = first
        .iter()
        .find(|f| {
            f.rule == "PW-003"
                && f.sources
                    .iter()
                    .any(|s| s.starts_with("SYSVOL GPO permissions"))
        })
        .expect("BOB's PW-003 through WriteGPOFiles");
    // Today's list and one written before `sources_exact` (BOB's finding
    // cites the part, so it is kept).
    for recorded in [None, Some(legacy_keys())] {
        let legacy = recorded.is_some();
        let (r, verdict, details) = compare(&b, recorded, &a, &bob.fingerprint);
        assert!(
            !r.resolved.iter().any(|x| x.fingerprint == bob.fingerprint),
            "legacy {legacy}"
        );
        assert_eq!(verdict, retest::Verdict::CantTell, "legacy {legacy}");
        assert_eq!(
            details,
            ["SYSVOL GPO permissions (SYS.LOCAL) was not collected in this collection"],
            "legacy {legacy}"
        );
    }
    let _ = std::fs::remove_dir_all(after);
}

/// A part the baseline had edges from and this run did not collect holds
/// every attack-path finding, even one read over LDAP: its path may have
/// run through those edges.
#[test]
fn a_part_the_baseline_had_and_this_run_lacks_holds_attack_paths() {
    let before = with_files("had-before", |_| {}, true);
    let after = with_files("had-after", password_mode, false);
    let (b, a) = (
        load_from(std::slice::from_ref(&before)),
        load_from(std::slice::from_ref(&after)),
    );
    let fp = carol_finding(&run(&b.0, &b.1)).fingerprint.clone();
    for recorded in [None, Some(legacy_keys())] {
        let legacy = recorded.is_some();
        let (r, verdict, details) = compare(&b, recorded, &a, &fp);
        assert!(
            !r.resolved.iter().any(|x| x.fingerprint == fp),
            "legacy {legacy}"
        );
        assert_eq!(verdict, retest::Verdict::CantTell, "legacy {legacy}");
        let d = details.join(" ");
        assert!(
            d.contains("SYSVOL GPO permissions (SYS.LOCAL): not collected")
                && d.contains("NETLOGON logon script permissions (SYS.LOCAL): not collected")
                && !d.contains("GPP"),
            "legacy {legacy}: {d}"
        );
    }
    // No SYSVOL data at all this run (a SharpHound collection): held too,
    // and the parts are still named.
    let none = with_files("had-none", |_| {}, false);
    std::fs::remove_file(none.join(SIDECAR)).unwrap();
    let n = load_from(std::slice::from_ref(&none));
    let (_, verdict, details) = compare(&b, None, &n, &fp);
    assert_eq!(verdict, retest::Verdict::CantTell);
    assert!(
        details[0]
            .contains("SYSVOL GPO permissions (SYS.LOCAL): no SYSVOL data in this collection"),
        "{details:?}"
    );
    for d in [before, after, none] {
        let _ = std::fs::remove_dir_all(d);
    }
}

#[test]
fn completeness_shows_each_part() {
    let (g, stats) = load_from(&[dir()]);
    let all = run(&g, &stats);
    let p = pathwarden_core::posture::compute(
        &g,
        &all,
        &[],
        &RuleSettings {
            now: NOW,
            ..RuleSettings::default()
        },
    );
    assert_eq!(p.sysvol.len(), 1);
    assert_eq!(p.sysvol[0].domain, "SYS.LOCAL");
    assert_eq!(p.sysvol[0].users_with_logon_scripts, 2);
    // Without SYSVOL data nothing is added (and the posture JSON is as before).
    let other = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/forest");
    let (g, stats) = load_from(&[other]);
    let p = pathwarden_core::posture::compute(
        &g,
        &run(&g, &stats),
        &[],
        &RuleSettings {
            now: NOW,
            ..RuleSettings::default()
        },
    );
    assert!(p.sysvol.is_empty());
    assert!(!serde_json::to_string(&p).unwrap().contains("sysvol"));
}

/// The explorer's kind table names the SYSVOL source for its edges (for
/// Explore's source filter), with native kinds in their usual order.
#[test]
fn explorer_kinds_name_the_sysvol_source() {
    use pathwarden_core::explore::{self, ExploreGraph};
    let (g, _) = load_from(&[dir()]);
    let x = ExploreGraph::decode(&explore::encode(&g, &[], &[])).unwrap();
    let names: Vec<&str> = x.kinds_info.edges.iter().map(|e| e.name.as_str()).collect();
    let native: Vec<&str> = EdgeKind::ALL.iter().map(|k| k.as_str()).collect();
    assert_eq!(&names[..native.len()], &native[..]);
    let pos = |n: &str| names.iter().position(|x| *x == n).unwrap();
    assert!(pos("WriteGPOFiles") < pos("WriteLogonScript"));
    assert!(pos("WriteLogonScript") < pos("ManagesHost"));
    let gpo = x
        .kinds_info
        .edges
        .iter()
        .find(|e| e.name == "WriteGPOFiles")
        .unwrap();
    assert_eq!(gpo.sources.len(), 1, "{gpo:?}");
    assert!(x
        .kinds_info
        .edges
        .iter()
        .filter(|e| e.name == "MemberOf")
        .all(|e| e.sources.is_empty()));
}
